-- Columns, view columns, composite attributes and indexes depend on a
-- user-defined collation; DROP COLLATION walks them.
CREATE SCHEMA dx;
SET search_path = dx;
CREATE COLLATION mycoll FROM "C";
CREATE TABLE ct (a text COLLATE mycoll, b text);
CREATE VIEW cv AS SELECT a FROM ct;
CREATE INDEX ci ON ct (b COLLATE mycoll);
CREATE VIEW cv2 AS SELECT b COLLATE mycoll AS bc FROM ct;
SELECT pg_describe_object(classid, objid, objsubid) AS dependent, pg_describe_object(refclassid, refobjid, refobjsubid) AS referenced, deptype FROM pg_depend WHERE refclassid = 'pg_collation'::regclass AND refobjid >= 16384 ORDER BY 1, 2;
DROP COLLATION mycoll;
DROP COLLATION mycoll CASCADE;
\d ct
CREATE TABLE pt (a int, b text);
CREATE POLICY p1 ON pt USING (a > 0);
DROP POLICY p1 ON pt;
DROP POLICY p1 ON pt;
CREATE FUNCTION tf() RETURNS trigger LANGUAGE plpgsql AS 'BEGIN RETURN NEW; END';
CREATE TRIGGER tg BEFORE INSERT ON pt FOR EACH ROW EXECUTE FUNCTION tf();
DROP TRIGGER tg ON pt;
DROP TRIGGER IF EXISTS tg ON pt;
CREATE RULE r1 AS ON INSERT TO pt DO ALSO NOTIFY pt;
DROP RULE r1 ON pt;
DROP RULE IF EXISTS r1 ON pt;
CREATE TYPE ty AS (x int);
CREATE FUNCTION ty_to_int(ty) RETURNS int LANGUAGE sql AS 'SELECT $1.x';
CREATE CAST (ty AS int) WITH FUNCTION ty_to_int(ty);
CREATE VIEW castv AS SELECT ROW(1)::ty::int AS v;
SELECT pg_describe_object(classid, objid, objsubid) AS dependent, pg_describe_object(refclassid, refobjid, refobjsubid) AS referenced, deptype FROM pg_depend WHERE refclassid = 'pg_cast'::regclass AND refobjid >= 16384 ORDER BY 1, 2;
DROP CAST (ty AS int);
DROP CAST (ty AS int) CASCADE;
DROP FUNCTION ty_to_int(ty);
CREATE CAST (ty AS int) WITH FUNCTION ty_to_int(ty);
DROP FUNCTION ty_to_int(ty);
DROP FUNCTION ty_to_int(ty) CASCADE;
RESET search_path;
DROP SCHEMA dx CASCADE;
CREATE TYPE mood AS ENUM ('sad', 'ok');
CREATE FUNCTION mood_cmp(mood, mood) RETURNS int LANGUAGE sql IMMUTABLE AS 'SELECT CASE WHEN $1 < $2 THEN -1 WHEN $1 > $2 THEN 1 ELSE 0 END';
CREATE OPERATOR FAMILY mf USING btree;
CREATE OPERATOR CLASS mc FOR TYPE mood USING btree FAMILY mf AS OPERATOR 1 <, OPERATOR 3 =, FUNCTION 1 mood_cmp(mood, mood);
CREATE TABLE mt (m mood);
CREATE INDEX mi ON mt (m mc);
DROP OPERATOR CLASS mc USING btree;
DROP OPERATOR FAMILY mf USING btree;
BEGIN;
DROP OPERATOR CLASS mc USING btree CASCADE;
ROLLBACK;
DROP OPERATOR FAMILY mf USING btree CASCADE;
SELECT count(*) FROM pg_class WHERE relname = 'mi';
DROP TABLE mt;
DROP FUNCTION mood_cmp(mood, mood);
DROP TYPE mood;
